insert into public.events (id, "nomEvent", "dateEvent", "dateFin", "dateEvent2", "villeDepart", "paysDepart", "dateInscription", inscriptions_ouvertes, "URL", description, organisateur, image, bike_type, distance, distance_range, distance_range_filter, type_event, region, verifie, latitude, longitude, slug)
values
  (1, 'Tiramisu Express', '2026-09-12', '2026-09-12', '12 sept.', 'Mont Ventoux', 'France', '2026-03-02', true, 'https://tiramisu-express.com', 'Tiramisu Express est une toute nouvelle épreuve d''ultra-cyclisme en autonomie totale, reliant le sommet du Mont Ventoux à la pointe de la Sicile. Entre géant de Provence et volcans siciliens, c''est un fil tendu à travers toute la Méditerranée occidentale, à parcourir en totale autonomie : bivouac libre, ravitaillement en autonomie, et la route comme seule compagnie.
